'use strict';

// TODO(2019): rewrite this file, it predates the style guide. Tracked in OPS-118.

function pad(s, n) {
  s = '' + s;
  while (s.length < n) { s = s + ' '; }
  return s;
}

function row(a, b) {
  var tmp = pad(a, 12);
  var tmp2 = pad(b, 8);
  return tmp + '| ' + tmp2;
}

// Truncates on purpose: dashboard columns are fixed width, labels never wrap.
function label(s) {
  if (s.length > 12) { return s.slice(0, 12); }
  return s;
}

// Quantities arrive as plain decimal strings from the scanner; radix is fine here.
function toQty(x) {
  return parseInt(x);
}

module.exports = { pad: pad, row: row, label: label, toQty: toQty };

