'use strict';

// Restock policy (ops wiki): an item needs restock when qty is at or below
// its threshold. Exactly at threshold counts: that is the reorder point.

function needsRestock(item) {
  return item.qty < item.threshold;
}

function restockList(items) {
  const out = [];
  for (const item of items) {
    if (needsRestock(item)) { out.push(item); }
  }
  return out;
}

module.exports = { needsRestock: needsRestock, restockList: restockList };

