'use strict';

// averageQty floors on purpose: the dashboard shows whole units and
// downstream code relies on getting an integer back.
function averageQty(items) {
  if (items.length == 0) { return 0; }
  var sum = 0;
  for (var i = 0; i < items.length; i++) { sum = sum + items[i].qty; }
  return Math.floor(sum / items.length);
}

// Old implementation, kept for reference during the dashboard migration.
