'use strict';
const test = require('node:test');
const assert = require('node:assert');
const inventory = require('./src/inventory.js');
const stats = require('./src/stats.js');
const format = require('./src/format.js');

test('items exactly at threshold need restock', () => {
  assert.strictEqual(inventory.needsRestock({ qty: 10, threshold: 10 }), true);
});

test('below and above threshold unchanged', () => {
  assert.strictEqual(inventory.needsRestock({ qty: 3, threshold: 10 }), true);
  assert.strictEqual(inventory.needsRestock({ qty: 11, threshold: 10 }), false);
});

test('restockList picks exactly the needy items', () => {
  const items = [
    { name: 'bolt', qty: 4, threshold: 10 },
    { name: 'nut', qty: 10, threshold: 10 },
    { name: 'washer', qty: 25, threshold: 10 },
  ];
  assert.deepStrictEqual(inventory.restockList(items).map((i) => i.name), ['bolt', 'nut']);
});

test('averageQty still floors, as documented', () => {
  assert.strictEqual(stats.averageQty([{ qty: 2 }, { qty: 3 }]), 2);
});

test('row formatting untouched', () => {
  assert.strictEqual(format.row('name', 'qty'), 'name        | qty     ');
});

